  var resumeTime = new Date(override.endDateTime * 1000);
  var content = `<div class='ibp2_notification_bar ibp2-row'>Your Inbox is currently ${override.state} and your schedule will resume ${ibp2_notification_bar_date_format(resumeTime)}.<div class="ibp2-notification-bar-close">${svgIBP2Close}</div></div>`
