/**
   * Displays an announcement about the new Meeting Polls feature in the Compose view
   */
  function announce_meeting_poll() {
    if (document.querySelector('.b4g-meeting-poll-announcement')) {
      // If the announcement is already present, do nothing
      return;
    }
    let buttonObserver, composeObserver;

    const buttonEls = document.querySelectorAll('.b4g-bcal-features-button');
    const buttonEl = buttonEls.length > 0 ? buttonEls[0] : null;
    const announcementEl = Object.assign(
      document.createElement("dialog"), 
    {
      className: "b4g-meeting-poll-announcement",
      innerHTML: `
        <img 
          src="${BOOMERANG_URL}site_media/img/group-poll/announcement-image.webp"
          srcset="${BOOMERANG_URL}site_media/img/group-poll/announcement-image@2x.webp 2x"
          loading="lazy"
          alt="Illustration of a person sending a meeting poll" />
          <button type="button" class="b4g-close-button" data-action="close" data-track="close">
            <svg width="17" height="16" viewBox="0 0 17 16" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M8.41797 0C12.8362 0 16.418 3.58172 16.418 8C16.418 12.4183 12.8362 16 8.41797 16C3.99969 16 0.417969 12.4183 0.417969 8C0.417969 3.58172 3.99969 0 8.41797 0ZM11.2021 5.21582C10.914 4.92767 10.4465 4.92792 10.1582 5.21582L8.41797 6.95605L6.67773 5.21582C6.38943 4.92792 5.92194 4.92767 5.63379 5.21582C5.34564 5.50397 5.34589 5.97146 5.63379 6.25977L7.37402 8L5.63379 9.74023C5.34589 10.0285 5.34564 10.496 5.63379 10.7842C5.92194 11.0723 6.38943 11.0721 6.67773 10.7842L8.41797 9.04395L10.1582 10.7842C10.4465 11.0721 10.914 11.0723 11.2021 10.7842C11.4903 10.496 11.49 10.0285 11.2021 9.74023L9.46191 8L11.2021 6.25977C11.49 5.97146 11.4903 5.50397 11.2021 5.21582Z" fill="white"/>
            </svg>
          </button>
          <aside>
            <div class="eyebrow_heading">
              <img 
                src="${BOOMERANG_URL}site_media/img/group-poll/boomerang-mini-logo.webp"
                srcset="${BOOMERANG_URL}site_media/img/group-poll/boomerang-mini-logo@2x.webp 2x"
                loading="lazy"
                alt="Miniature Boomerang logo" />
              <span>Now in Boomerang</span>
            </div>
            <h2>Introducing a better way to schedule group meetings</h2>
            <p>Boomerang’s <strong>Meeting Polls</strong> make it effortless to find a time that works for everyone. No logins, no ads—just a fast, easy way to schedule group meetings.</p>
            <button type="button" class="primary" data-action="close" data-try="true" data-track="try">Try it out</button>
          </aside>`});
    announcementEl.style.zIndex = "9999";
    announcementEl.style.position = "fixed";
    announcementEl.style.height = "395px";
    announcementEl.style.bottom = "20px";
    announcementEl.style.right = "20px";

    const arrowEl = Object.assign(document.createElement("div"), 
    { className: "b4g-meeting-poll-arrow", innerHTML: `<span></span>` });
      arrowEl.style.zIndex = "9999";
      arrowEl.style.position = "fixed";
      arrowEl.style.bottom = "20px";
      arrowEl.style.right = "20px";

    announcementEl.addEventListener("click", (e) => {
      if ((e.target.tagName === "BUTTON" && e.target.dataset.action === "close")) {
        announcementEl?.close();
        announcementEl?.remove();
        arrowEl?.remove();
        document.querySelectorAll('.b4g-bcal-features-button').forEach(el => el.classList.remove('announce-meeting-poll'));
        if (buttonObserver)  buttonObserver.disconnect();
        if (composeObserver) composeObserver.disconnect();
        if (e.target.dataset.try) {
            buttonEl.click();
            let attempts = 0;
            // Attempt up to 100 times, checking each frame so animation can run right away
            function waitForPollRow() {
              attempts++;
              const meetingPollRow = document.querySelector('#bcal_menu_group_poll_row');
              if (meetingPollRow) {
                meetingPollRow.classList.add('meeting-poll-row-pulse-one-time','prevent-hover');
                /** Prevent the hover effect from being triggered immediately 
                 * because the placement of the pointer happens to be over 
                 * share free/busy when the menu opens */
                const listener = (e) => { 
                  meetingPollRow.classList.remove('prevent-hover');
                  meetingPollRow.removeEventListener('pointerover', listener);
                };
                meetingPollRow.addEventListener('pointerover', listener);
              } else if (++attempts < 100) {
                requestAnimationFrame(waitForPollRow);
              }
            }
            waitForPollRow();
        }
        track_event([ "announce_meeting_poll", `click_${e.target.dataset.track || ''}`]);
      }
      e.stopPropagation();
      e.preventDefault();
    });

    if (buttonEl) {
      buttonEls.forEach(el => el.classList.add('announce-meeting-poll'));    
      
      function updateAnnouncementPosition() {
        requestAnimationFrame(() => {
          const rect = buttonEl.getBoundingClientRect();
          announcementEl.style.bottom = `${window.innerHeight - rect.top + 16}px`;
          announcementEl.style.left = `${rect.left + rect.width}px`;
          announcementEl.style.transform = "translateX(-90%)";
          const announcementRect = announcementEl.getBoundingClientRect();
          arrowEl.style.top = `${announcementRect.top + announcementRect.height}px`;
          arrowEl.style.left = `${rect.left + rect.width * 0.5}px`;
          arrowEl.style.transform = "translateX(-50%)";
        });
      }
      updateAnnouncementPosition();

      // Reposition if the button moves (using ResizeObserver)
      if (window.ResizeObserver) {
        buttonObserver = new ResizeObserver(updateAnnouncementPosition);
        buttonObserver.observe(document.body);
      }

      // Also watch for Gmail moving the compose window (maximize/pop-out)
      const composeContainer = buttonEl.closest('[role="dialog"]') || buttonEl.offsetParent;
      if (composeContainer && window.MutationObserver) {
        composeObserver = new MutationObserver(updateAnnouncementPosition);
        composeObserver.observe(composeContainer, {
          attributes: true,
          attributeFilter: ['style', 'class']
        });
      }
    }
    document.body.appendChild(announcementEl);
    announcementEl.show();
    document.body.appendChild(arrowEl);
    write_to_html5_storage("b4g_meeting_poll_announcement_shown", true);
    meetingPollAnnouncementShownDuringThisSession = true;
    $.ajax({
      url: "https://b4g.baydin.com/mailcruncher/markMeetingPollAnnouncementAsDismissed",
      method: "GET",
      data: {
        "guser": get_gmail_user()
      },
      xhr: xhr_with_credentials,
    });
    track_event([ "announce_meeting_poll", "open" ]);
  }

