async function review_prompt_check(trigger) {
  
  if (await isPromptEligible(trigger)) {
    // Prevent potential replacement with a duplicate CWS/G2 prompt due to delayed CWS/G2 prompt checks
    if (REVIEW_PROMPT_CHECK_TIMEOUT) clearTimeout(REVIEW_PROMPT_CHECK_TIMEOUT);

    let eventName = 'cwsReviewPrompt'
    show_review_dialog(
      `
      <div class="b4g-corner-review-prompt-flex-container">
        <p style='font-size:14px;font-weight:600;'>What do you think of Boomerang so far?</p>
        
        <div class="b4g-star-rating">
          <label for="star1">
            <input type="radio" id="star1" name="rating" value="1" />
          </label>
          <label for="star2">
            <input type="radio" id="star2" name="rating" value="2" />
          </label>
          <label for="star3">
            <input type="radio" id="star3" name="rating" value="3" />
          </label>
          <label for="star4">
            <input type="radio" id="star4" name="rating" value="4" />
          </label>
          <label for="star5">
            <input type="radio" id="star5" name="rating" value="5" />
          </label>
        </div>

        <p class='closeLink' style='cursor: pointer; text-decoration: underline; line-height:27px; align-self:center;'>I'm not sure yet</p>

      </div>
      `,
      trigger
    )

    $('.b4g-star-rating label').mouseover((e) => {
      var sel = $(e.currentTarget).find('input').val();
      var options = $('.b4g-star-rating label');

      for (var i = 0; i < sel; i++) {
        $(options[i]).css('color', 'gold')
      }
      for (var i = sel; i < options.length; i++) {
        $(options[i]).css('color', 'grey')
      }
    })

    track_event([`${eventName}_${trigger}`, "Open"])

  }
}

function _review_prompt_on_scheduling_feature_if_necessary_handler_helper($composeContainer, delayBeforePrompting) {
  let bookableMLCInserted = $composeContainer.hasClass('b4g_click_calendar_book');
  let bookableLinkInserted = $composeContainer.hasClass('b4g_click_calendar_book_link');
  let suggestTimesMLCInserted = $composeContainer.hasClass('b4g_click_calendar_suggest');
  let shareFreeBusyMLCInserted = $composeContainer.hasClass('b4g_click_calendar_freebusy');

  function promptForSchedulingFeatures() {
    if (bookableMLCInserted) {
      review_prompt_check('mlc-bookable');
    }
    if (bookableLinkInserted) {
      review_prompt_check('link-bookable');
    }
    if (suggestTimesMLCInserted) {
      review_prompt_check('mlc-suggest-times');
    }
    if (shareFreeBusyMLCInserted) {
      review_prompt_check('mlc-share-free-busy');
    }

  }

  if (delayBeforePrompting) {
    REVIEW_PROMPT_CHECK_TIMEOUT = setTimeout(() => {
      // Wait until after gmail notification hijack is finished
      promptForSchedulingFeatures();
    }, 10000)
  } else {
    promptForSchedulingFeatures();
  }

}

window.testReview = review_prompt_check

function show_nag_dialog(message, include_ok_button, closeLinkText) {

    if (browser_name === "Old Safari"){
        alert(message);
    }
    else
    {
        var dialog, frameDoc = get_frame();
        $(".dialogdiv").remove();
        if(closeLinkText)
        {
            dialog = "<div class='dialogdiv' style='display:none;'>" +
                message +
                "<span style='float:right; margin:0 15px 0 0;'>" +
                    "<span class='closeLink' style='cursor: pointer; text-decoration: underline;'>"+ closeLinkText + "</span>" +
                "</span>" +
            "</div>";
        }
        else
        {
            dialog = "<div class='dialogdiv' style='display:none;'>"+ message+"</div>";
        }
        $("body", frameDoc).append($(dialog));

        if (message.toLowerCase().indexOf("invite your contacts") !== -1) {
            $('#multi-friend-button').click(function () {
                track_event(["multi-friend-selector", "click", "nag screen"]);
                call_contacts_function_after_logged_in(show_multi_friend_dialog);
            });
        }
        $("#tweet-button").click(b4g_tweet);

        var dialogParams = {
                title: 'Boomerang for Gmail',
                modal: true,
                closeOnEscape: true,
                width: 370
            };
        if (include_ok_button){
            dialogParams["buttons"] = {
                "Ok": {
                    text: 'OK Fine!',
                    'class': 'b4g-button dialog-gray',
                    click : function() { $(this).dialog("destroy"); }
                }
            };
        }
        $(".dialogdiv",frameDoc).dialog(dialogParams);
        $('.closeLink').click(function () {
            $('.dialogdiv').dialog('close');
        });

        if(which_gmail() === NEW_GMAIL) {
            $(".dialogdiv").parent().addClass("gm-customize-modal gm-nag-modal");
        }

        fix_all_dialog_links();
    }
}

// Show the first step of the CWS/G2 review prompt: dialog asking what the user thinks of Boomerang,
// using a rating of 1-5 stars
function show_review_dialog(message, trigger) {
  var dialog, frameDoc = get_frame();
  $(".dialogdiv").remove();
  let eventName = 'cwsReviewPrompt';

  dialog = `
    <div class='dialogdiv' style='display:none;'>
      ${message}
    </div>
  `;

  $("body", frameDoc).append($(dialog));

  var dialogParams = {
    modal: false,
    closeOnEscape: true,
    width: 270
  };
  $(".dialogdiv", frameDoc).dialog(dialogParams);
  $('.closeLink').click(function () {
    $('.dialogdiv').dialog('close');
    track_event([`${eventName}_${trigger}`, `Initial_dialog_closed`])
    // Decision 5/1/24: If you dismiss the initial corner prompt with the "I'm not sure yet" link, we mark the prompt as dismissed and you'll never see it again
    mark_review_prompt_as_dismissed();
  });
  
  $('.dialogdiv .b4g-star-rating input').click((e) => {
    if (['1', '2', '3', '4'].includes(e.currentTarget.value)) {
      $('.dialogdiv').dialog('close');
      openReviewFlowFeedbackDialog(e.currentTarget.value, trigger);
    } else {
      $('.dialogdiv').dialog('close');
      openReviewFlowReviewDialog(trigger);
    }
    track_event([`${eventName}_${trigger}`, `Rated_${e.currentTarget.value}`])
  });

  $(".dialogdiv").parent().addClass("gm-customize-modal gm-review-corner-prompt");

  fix_all_dialog_links();

  mark_review_prompt_as_seen();
}

