let UPDATE_REVIEW_STATUS_ENDPOINT = 'https://b4g.baydin.com/mailcruncher/updatecwsstatus'
function mark_review_prompt_as_reviewed() {
  // User has reviewed.  Prompt won't be shown again
  $.ajax({
    url: UPDATE_REVIEW_STATUS_ENDPOINT,
    type: "POST",
    data: {
      action: 'reviewed'
    },
    xhr: xhr_with_credentials,
    success: function(response) {
    }
  });

  var guser = get_gmail_user();
  write_to_html5_storage(`b4g_cws_prompt_eligible-${guser}`, false);
}

function mark_review_prompt_as_dismissed() {
  // User has dismissed prompt.  Prompt won't be shown again
  $.ajax({
    url: UPDATE_REVIEW_STATUS_ENDPOINT,
    type: "POST",
    data: {
      action: 'dismissed'
    },
    xhr: xhr_with_credentials,
    success: function(response) {
    }
  });

  var guser = get_gmail_user();
  write_to_html5_storage(`b4g_cws_prompt_eligible-${guser}`, false);
}

function mark_review_prompt_as_seen() {
  // User has seen the prompt
  $.ajax({
    url: UPDATE_REVIEW_STATUS_ENDPOINT,
    type: "POST",
    data: {
      action: 'seen'
    },
    xhr: xhr_with_credentials,
    success: function(response) {
    }
  });
  var guser = get_gmail_user();
  localStorage.removeItem(`b4g_cws_prompt_eligible-${guser}`);
}

