window.getTestGroup = async function(email, salt, numberOfTestGroups) {
  // Note: since this uses javascript's built in SubleCrypto interface, this is an asynchronous function
  // Returns a number (0 through number of test groups - 1) that will be the test group of a user
  // for a test. 
  // Matches logic in ab_testing.py
  // Uses SubleCrypto: https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto

  // Combine input email & salt into an input string
  let keyString = String(email).toLowerCase() + String(salt).toLowerCase()

  let encoder = new TextEncoder();
  let encodedString = encoder.encode(keyString);

  // Use the sha1 algorithm to convert our input string into a hexidecimal value
  let hashBuffer = await crypto.subtle.digest("SHA-1", encodedString);
  const hashArray = Array.from(new Uint8Array(hashBuffer)); // convert buffer to byte array
  const hexDigest = hashArray
    .map((b) => b.toString(16).padStart(2, "0"))
    .join(""); // convert bytes to hex string

  // Convert the value to an integer, and take the mod of the number of test groups we want
  // We need to use the BigInt type to get an accurate modulo result
  let myBigInt = BigInt(`0x${hexDigest}`)
  let testGroup = Number(myBigInt % BigInt(numberOfTestGroups))

  return testGroup

}

