let REVIEW_PROMPT_SECOND_COHORT_START_TIMESTAMP = 1721674800000;  // Monday, July 22nd, 2024 12pm Pacific as a timestamp in milliseconds
let secondCohortStartDate;
let thirdCohortStartDate;
let fourthCohortStartDate;
let fifthCohortStartDate;
let sixthCohortStartDate;
let seventhCohortStartDate;
let oneInTenChanceStartDate;
function updateReviewCohortStartDates() {
  // This needs to be a helper function that we call as needed instead of us just setting these date variables right away when the bookmarklet loads
  // The reason for this is we need to wait for Date.js to be initialized
  secondCohortStartDate = new Date(REVIEW_PROMPT_SECOND_COHORT_START_TIMESTAMP);
  thirdCohortStartDate = secondCohortStartDate.clone().addWeeks(6);
  fourthCohortStartDate = secondCohortStartDate.clone().addWeeks(12);
  fifthCohortStartDate = secondCohortStartDate.clone().addWeeks(18);
  sixthCohortStartDate = secondCohortStartDate.clone().addWeeks(24);
  seventhCohortStartDate = secondCohortStartDate.clone().addWeeks(30);
  oneInTenChanceStartDate = secondCohortStartDate.clone().addWeeks(36);
}
function experiment3687IsUserInEligibleTestCohortOrTenPercentChanceSucceeds(testGroup) {
  // Depending on the current time, this function will do one of the following things:
    // If before REVIEW_PROMPT_SECOND_COHORT_DEPLOY_TIMESTAMP: we return true if the testGroup is less than 15 (user belongs to a test group in the range 0-14)
    // If after REVIEW_PROMPT_SECOND_COHORT_DEPLOY_TIMESTAMP: we return true if the testGroup is in the current active range of groups (which advances every 6 weeks)
      // Second cohort: groups 15-29
      // Third cohort: groups 30-44
      // Fourth cohort: groups 45-59
      // Fifth cohort: groups 60-74
      // Sixth cohort: groups 75-89
      // Seventh and final cohort: groups 90-99
    // If after the end of the final cohort's 6 week time window, we disregard the testGroup variable and just return true

  let now = new Date();
  updateReviewCohortStartDates();

  if (now < secondCohortStartDate) {
    // Cohort 1
    track_event(["CWS_groups_0_14_active", "CWS_groups_0_14_active"])
    if (testGroup < 15) return true;
  } else if (now < thirdCohortStartDate) {
    // Cohort 2
    track_event(["CWS_groups_15_29_active", "CWS_groups_15_29_active"])
    if (testGroup >= 15 && testGroup < 30) return true; 
  } else if (now < fourthCohortStartDate) {
    // Cohort 3
    track_event(["CWS_groups_30_44_active", "CWS_groups_30_44_active"])
    if (testGroup >= 30 && testGroup < 45) return true; 
  } else if (now < fifthCohortStartDate) {
    // Cohort 4
    track_event(["CWS_groups_45_59_active", "CWS_groups_45_59_active"])
    if (testGroup >= 45 && testGroup < 60) return true; 
  } else if (now < sixthCohortStartDate) {
    // Cohort 5
    track_event(["CWS_groups_60_74_active", "CWS_groups_60_74_active"])
    if (testGroup >= 60 && testGroup < 74) return true; 
  } else if (now < seventhCohortStartDate) {
    // Cohort 6
    track_event(["CWS_groups_75_89_active", "CWS_groups_75_89_active"])
    if (testGroup >= 75 && testGroup < 90) return true; 
  } else if (now < oneInTenChanceStartDate) {
    // Cohort 7
    track_event(["CWS_groups_90_99_active", "CWS_groups_90_99_active"])
    if (testGroup >= 90 && testGroup < 100) return true; 
  } else if (now >= oneInTenChanceStartDate) {
    // Always return true - the 1 in ten chance is checked later on after the trigger hits check
    return true; 
  }

  return false;
}

async function experiment3687IsTestGroup(email) {
  // 15% chance of a user being eligible
  let bugNumber = '3687';
  let testGroupOutOf100 = await getTestGroup(email, bugNumber, 100);
  if (experiment3687IsUserInEligibleTestCohortOrTenPercentChanceSucceeds(testGroupOutOf100)) {
    return  true;
  } else {
    return false;
  }
}



